def collect_tags(posts, seen=None):
    if seen is None:
        seen = []
    for post in posts:
        if not post:
            continue
        for tag in post.get("tags", []):
            if not tag:
                continue
            tag_lc = tag.lower()
            if tag_lc not in seen:
                seen.append(tag_lc)
    return seen

def is_eligible(age, income, student, veteran, state, score):
    """Determine eligibility based on age, income, student status, veteran status, state, and score."""
    # Senior applicants have a separate rule
    if (age > 65 and income < 30000) or age > 70:
        return (score > 500) or veteran

    # General eligibility
    if (age >= 18 and income < 40000) or (student and age < 26) or veteran:
        if state in {"NY", "NJ"} or (state == "CT" and score > 600):
            return True
        if (score > 700 and income < 60000) or (veteran and score > 550):
            return True

    return False

def _grade_from_average(avg):
    if avg >= 90:
        return "A"
    if avg >= 80:
        return "B"
    if avg >= 70:
        return "C"
    return "F"

def grade_summary(math=None, science=None, english=None):
    out = {}
    for name, scores in (("math", math), ("science", science), ("english", english)):
        if scores:
            avg = sum(scores) / len(scores)
            out[name] = _grade_from_average(avg)
    return out

def to_csv(rows, columns):
    lines = [",".join(columns)]
    for row in rows:
        values = []
        for col in columns:
            value = row.get(col)
            if value is None:
                values.append("")
                continue
            if isinstance(value, str):
                if "," in value:
                    values.append('"' + value + '"')
                else:
                    values.append(value)
            else:
                values.append(str(value))
        lines.append(",".join(values))
    return "\n".join(lines) + "\n"

